```javascript
// ko-debug.js

function levenshteinDistance(str1, str2) {
    const m = str1.length;
    const n = str2.length;
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i <= m; i++) dp[i][0] = i;
    for (let j = 0; j <= n; j++) dp[0][j] = j;

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            if (str1[i-1] === str2[j-1]) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                dp[i][j] = 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
            }
        }
    }

    return dp[m][n];
}

function diagnoseMissingProperty(viewModel, propertyName) {
    const availableProperties = Object.keys(viewModel).sort();

    let suggestion = null;
    let minDistance = Infinity;

    for (const prop of availableProperties) {
        const dist = levenshteinDistance(propertyName, prop);
        if (dist <= 3 && dist < minDistance) {
            minDistance = dist;
            suggestion = prop;
        } else if (dist <= 3 && dist === minDistance) {
            // If tie, return alphabetically first (already sorted)
            // Since we're iterating alphabetically and using strict <, we keep the first
        }
    }

    return {
        error: true,
        missingProperty: propertyName,
        availableProperties: availableProperties,
        suggestion: suggestion // null if no match
    };
}

function createDebugHelper(viewModel) {
    return {
        diagnoseMissingProperty: function(propertyName) {
            return diagnoseMissingProperty(viewModel, propertyName);
        }
    };
}

module.exports = { createDebugHelper, diagnoseMissingProperty };
```

